CREATE OR REPLACE FUNCTION public.distribute_community_pool(p_force boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$declare b pool_balance%rowtype;s pool_settings%rowtype;h uuid;seed text;ranking_total numeric;lottery_total numeric;winner_count int;begin perform pg_advisory_xact_lock(hashtext('community_pool_distribution'));select*into b from pool_balance where status='active'for update;if b.id is null then raise exception'NO_ACTIVE_POOL';end if;if not p_force and b.ends_at>now()then raise exception'POOL_NOT_DUE';end if;update pool_balance set status='distributing',updated_at=now()where id=b.id;select*into s from pool_settings where id;seed:=encode(gen_random_bytes(32),'hex');insert into pool_history(pool_id,week_label,amount_ton,winner_count,seed_hash)values(b.id,b.week_label,b.balance_ton,0,encode(digest(seed,'sha256'),'hex'))returning id into h;ranking_total:=b.balance_ton*s.ranking_share_percent/100;lottery_total:=b.balance_ton*s.lottery_share_percent/100;with scores as(select pp.user_id,sum(pp.points)::int points from pool_points pp join game_players gp on gp.id=pp.user_id where pp.pool_id=b.id and not gp.pvp_banned and gp.created_at<=now()-interval'7 days'and exists(select 1 from player_heroes x where x.user_id=pp.user_id)and exists(select 1 from pool_wallets w where w.user_id=pp.user_id)group by pp.user_id having sum(pp.points)>=s.minimum_points),ranked as(select*,row_number()over(order by points desc,user_id)pos from scores),awards as(select*,public.pool_ranking_share(pos::int) share from ranked where pos<=least(100,s.ranking_winner_limit))insert into pool_rewards(history_id,user_id,reward_type,position,amount_ton,idempotency_key)select h,user_id,'ranking',pos,greatest(.000000001,round(ranking_total*share,9)),'pool_reward:'||h||':ranking:'||user_id from awards on conflict do nothing;with scores as(select pp.user_id,sum(pp.points)::int points from pool_points pp join game_players gp on gp.id=pp.user_id where pp.pool_id=b.id and not gp.pvp_banned and gp.created_at<=now()-interval'7 days'and exists(select 1 from player_heroes x where x.user_id=pp.user_id)and exists(select 1 from pool_wallets w where w.user_id=pp.user_id)group by pp.user_id having sum(pp.points)>=s.minimum_points),draw as(select*,row_number()over(order by(-ln(greatest(.000000001,(('x'||substr(encode(digest(seed||user_id::text,'sha256'),'hex'),1,15))::bit(60)::bigint)::numeric/1152921504606846976)))/points)pick from scores)insert into pool_rewards(history_id,user_id,reward_type,amount_ton,idempotency_key)select h,user_id,'lottery',round(lottery_total/greatest(1,least(s.lottery_winner_count,(select count(*)from scores))),9),'pool_reward:'||h||':lottery:'||user_id from draw where pick<=s.lottery_winner_count on conflict do nothing;insert into pool_winners(history_id,user_id,winner_type,position,points)select h,r.user_id,r.reward_type,r.position,coalesce((select sum(points)::int from pool_points where pool_id=b.id and user_id=r.user_id),0)from pool_rewards r where r.history_id=h on conflict do nothing;select count(distinct user_id)::int into winner_count from pool_rewards where history_id=h;update pool_history set winner_count=winner_count where id=h;update pool_balance set status='distributed',distribution_key='pool_distribution:'||b.id,updated_at=now()where id=b.id;insert into pool_balance(week_label,starts_at,ends_at)values('Temporada '||to_char(now(),'IYYY-IW'),now(),now()+make_interval(days=>s.season_days));return h;end$function$;